    "code": "'use strict';\n/**\n * ============================================================================\n * O(1) LRU and Frequency-Bucketed LFU Cache Engine (build-lfu-lru-cache)\n * ============================================================================\n * Category: Linked Structures & Caching\n * Difficulty: Advanced (~35 min)\n * Primary Curriculum Unit: build-lfu-lru-cache\n * Related Units: lru-lfu-eviction-structures, singly-doubly-intrusive-lists, case-redis-skiplist-ziplist, separate-chaining-vs-open-addressing, amortized-analysis-potential\n *\n * Summary:\n *   Strict O(1) LRU and Shah-Mitra-Matani frequency-bucketed LFU caches built over sentinel-guarded intrusive doubly linked lists with zero heap-log overhead.\n *\n * Key Engineering Highlights:\n *   1. Sentinel-guarded doubly linked list eliminating null-pointer branches\n *   2. Shah-Mitra-Matani O(1) LFU cache with frequency-bucketed LRU tie-breaking\n *   3. Exact minFreq invariant maintenance across hits, promotions, and evictions\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Sentinel-Guarded Intrusive Doubly Linked List: Implement `addFront(node)` and `remove(node)` on `DoublyLinkedList`. Because `this.head` and `this.tail` are permanent dummy sentinel nodes, every real node always has non-null `node.prev` and `node.next`. `addFront` splices `node` between `head` and `head.next`; `remove` links `node.prev.next = node.next` and `node.next.prev = node.prev`.\n *   - Step 2: O(1) LRU Cache via Hash Map + Recency List: Implement `get(key)` and `put(key, value)` on `LRUCache`. - Most recently used node sits at `list.head.next`; least recently used sits at `list.tail.prev`. - On `get(key)`: unlink node and `addFront(node)`. - On `put(key, value)`: if `map.size === capacity`, evict `list.popBack()` and delete its key from `map`.\n *   - Step 3: Frequency Bucket Promotion & minFreq Invariant: Implement `_promote(node)` on `LFUCache`. When `node` moves from `oldFreq` to `oldFreq + 1`, remove it from `buckets.get(oldFreq)`. If that bucket becomes empty **and** `this.minFreq === oldFreq`, increment `this.minFreq = oldFreq + 1`. Then insert `node` at the front of `buckets.get(oldFreq + 1)`.\n *   - Step 4: LFU Insertion & Tie-Breaking LRU Eviction: Implement `put(key, value)` on `LFUCache`. 1. If `key` exists, update `node.value = value` and call `this._promote(node)`. 2. If at capacity, pop the LRU victim from `this.buckets.get(this.minFreq).popBack()` and delete it from `this.nodes`. 3. Insert the new node into bucket `1` and set `this.minFreq = 1`.\n * ============================================================================\n */\n\nclass DLNode {\n  constructor(key = null, value = null) {\n    this.key = key;\n    this.value = value;\n    this.freq = 1;\n    this.prev = null;\n    this.next = null;\n  }\n}\n\nclass DoublyLinkedList {\n  constructor() {\n    this.head = new DLNode();\n    this.tail = new DLNode();\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n    this.size = 0;\n  }\n\n  addFront(node) {\n    node.next = this.head.next;\n    node.prev = this.head;\n    this.head.next.prev = node;\n    this.head.next = node;\n    this.size++;\n  }\n\n  remove(node) {\n    node.prev.next = node.next;\n    node.next.prev = node.prev;\n    node.prev = null;\n    node.next = null;\n    this.size--;\n    return node;\n  }\n\n  popBack() {\n    if (this.size === 0) return null;\n    return this.remove(this.tail.prev);\n  }\n}\n\nclass LRUCache {\n  constructor(capacity) {\n    if (capacity < 1) throw new RangeError('Capacity must be >= 1');\n    this.capacity = capacity;\n    this.map = new Map();\n    this.list = new DoublyLinkedList();\n  }\n\n  get(key) {\n    const node = this.map.get(key);\n    if (!node) return -1;\n    this.list.remove(node);\n    this.list.addFront(node);\n    return node.value;\n  }\n\n  put(key, value) {\n    const existing = this.map.get(key);\n    if (existing) {\n      existing.value = value;\n      this.list.remove(existing);\n      this.list.addFront(existing);\n      return;\n    }\n    if (this.map.size === this.capacity) {\n      const evicted = this.list.popBack();\n      if (evicted) this.map.delete(evicted.key);\n    }\n    const node = new DLNode(key, value);\n    this.list.addFront(node);\n    this.map.set(key, node);\n  }\n}\n\nclass LFUCache {\n  constructor(capacity) {\n    if (capacity < 1) throw new RangeError('Capacity must be >= 1');\n    this.capacity = capacity;\n    this.minFreq = 0;\n    this.nodes = new Map();\n    this.buckets = new Map();\n  }\n\n  _getBucket(freq) {\n    let b = this.buckets.get(freq);\n    if (!b) { b = new DoublyLinkedList(); this.buckets.set(freq, b); }\n    return b;\n  }\n\n  _promote(node) {\n    const oldFreq = node.freq;\n    const oldBucket = this._getBucket(oldFreq);\n    oldBucket.remove(node);\n    if (oldBucket.size === 0) {\n      this.buckets.delete(oldFreq);\n      if (this.minFreq === oldFreq) this.minFreq = oldFreq + 1;\n    }\n    node.freq = oldFreq + 1;\n    this._getBucket(node.freq).addFront(node);\n  }\n\n  get(key) {\n    const node = this.nodes.get(key);\n    if (!node) return -1;\n    this._promote(node);\n    return node.value;\n  }\n\n  put(key, value) {\n    const existing = this.nodes.get(key);\n    if (existing) {\n      existing.value = value;\n      this._promote(existing);\n      return;\n    }\n    if (this.nodes.size === this.capacity) {\n      const minBucket = this.buckets.get(this.minFreq);\n      const evicted = minBucket.popBack();\n      if (minBucket.size === 0) this.buckets.delete(this.minFreq);\n      this.nodes.delete(evicted.key);\n    }\n    const node = new DLNode(key, value);\n    node.freq = 1;\n    this.minFreq = 1;\n    this._getBucket(1).addFront(node);\n    this.nodes.set(key, node);\n  }\n}\n\nmodule.exports = { DLNode, DoublyLinkedList, LRUCache, LFUCache };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n\n  // Test DoublyLinkedList\n  const dll = new DoublyLinkedList();\n  const n1 = new DLNode('a', 1), n2 = new DLNode('b', 2);\n  dll.addFront(n1);\n  dll.addFront(n2);\n  assert.equal(dll.size, 2);\n  assert.equal(dll.popBack().key, 'a');\n  assert.equal(dll.popBack().key, 'b');\n  assert.equal(dll.popBack(), null);\n\n  // Test LRUCache\n  const lru = new LRUCache(2);\n  lru.put(1, 10);\n  lru.put(2, 20);\n  assert.equal(lru.get(1), 10); // 2 is now LRU\n  lru.put(3, 30); // evicts 2\n  assert.equal(lru.get(2), -1);\n  assert.equal(lru.get(3), 30);\n\n  // Test LFUCache with LRU tie-breaking\n  const lfu = new LFUCache(2);\n  lfu.put(1, 1);\n  lfu.put(2, 2);\n  assert.equal(lfu.get(1), 1);   // freq(1)=2, freq(2)=1, minFreq=1\n  lfu.put(3, 3);                 // evicts key 2 (freq 1)\n  assert.equal(lfu.get(2), -1);\n  assert.equal(lfu.get(3), 3);   // freq(3)=2, minFreq=2\n  lfu.put(4, 4);                 // tie at freq=2: key 1 is older than key 3 -> evicts key 1\n  assert.equal(lfu.get(1), -1);\n  assert.equal(lfu.get(3), 3);\n  assert.equal(lfu.get(4), 4);\n  return true;\n}\nrunTests();\n",
