    "code": "'use strict';\n/**\n * ============================================================================\n * Open-Addressing Robin Hood Hash Map with Backward-Shift Deletion (build-robin-hood-hash-map)\n * ============================================================================\n * Category: Hashing & Sketches\n * Difficulty: Advanced (~35 min)\n * Primary Curriculum Unit: build-robin-hood-hash-map\n * Related Units: robin-hood-cuckoo-hashing, separate-chaining-vs-open-addressing, universal-k-independent-hashing, case-rust-hashbrown-swisstable, hashdos-siphash-random-seeds\n *\n * Summary:\n *   An open-addressed hash table implementing Celis Robin Hood displacement, early-exit lookups on PSL ordering, and tombstone-free backward-shift deletion.\n *\n * Key Engineering Highlights:\n *   1. Probe Sequence Length (PSL) displacement minimizing probe variance\n *   2. Early-exit search termination when current PSL exceeds occupant PSL\n *   3. Tombstone-free backward-shift deletion preventing probe degradation\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Probe Sequence Length (PSL) Arithmetic on Power-of-2 Ring: Implement `_psl(slotIdx, idealIdx)` to compute how many linear probes an entry at `slotIdx` has traveled from `idealIdx`. In a power-of-two table, `(slotIdx - idealIdx) & this._mask` handles wrap-around across index `0` in $O(1)$ without branches.\n *   - Step 2: Robin Hood Displacement Insertion: Implement `set(key, value)` with Robin Hood swap semantics. 1. If `(this._size + 1) > this._capacity * this._maxLoad`, double capacity via `this._resize(this._capacity * 2)`. 2. Walk linearly from `idx = this._idealIndex(key)`. If `cur.key === entry.key`, overwrite `cur.value`. 3. If `entry.psl > cur.psl`, swap `entry` and `this._slots[idx]` and continue probing with the displaced entry.\n *   - Step 3: Early-Exit Lookup on PSL Monotonicity: Implement `get(key)` with early termination. Because Robin Hood insertion guarantees that any key with a larger `psl` would have displaced an occupant with a smaller `cur.psl`, if `cur === null || psl > cur.psl`, the target key cannot exist further down the probe chain.\n *   - Step 4: Tombstone-Free Backward-Shift Deletion: Implement `delete(key)` using backward-shift deletion instead of tombstones. 1. Locate `key` at `idx` (returning `false` if absent). 2. Clear `this._slots[idx] = null` and decrement `this._size`. 3. While `next = (prev + 1) & _mask` is occupied and `this._slots[next].psl > 0`, shift `this._slots[next]` into `prev`, decrement its `psl`, and advance.\n * ============================================================================\n */\n\nfunction fnv1a32(key) {\n  const str = String(key);\n  let h = 0x811c9dc5;\n  for (let i = 0; i < str.length; i++) {\n    h ^= str.charCodeAt(i);\n    h = Math.imul(h, 0x01000193);\n  }\n  return h >>> 0;\n}\n\nclass RobinHoodHashMap {\n  constructor(initialCapacity = 16, maxLoadFactor = 0.75) {\n    let cap = 1;\n    while (cap < Math.max(8, initialCapacity)) cap <<= 1;\n    this._capacity = cap;\n    this._mask = cap - 1;\n    this._maxLoad = maxLoadFactor;\n    this._size = 0;\n    this._slots = new Array(cap).fill(null);\n  }\n\n  get size() { return this._size; }\n  get capacity() { return this._capacity; }\n\n  _idealIndex(key) {\n    return fnv1a32(key) & this._mask;\n  }\n\n  _psl(slotIdx, idealIdx) {\n    return (slotIdx - idealIdx) & this._mask;\n  }\n\n  set(key, value) {\n    if ((this._size + 1) > this._capacity * this._maxLoad) {\n      this._resize(this._capacity * 2);\n    }\n    let idx = this._idealIndex(key);\n    let entry = { key, value, ideal: idx, psl: 0 };\n\n    while (true) {\n      const cur = this._slots[idx];\n      if (cur === null) {\n        this._slots[idx] = entry;\n        this._size++;\n        return this;\n      }\n      if (cur.key === entry.key) {\n        cur.value = entry.value;\n        return this;\n      }\n      if (entry.psl > cur.psl) {\n        this._slots[idx] = entry;\n        entry = cur;\n      }\n      idx = (idx + 1) & this._mask;\n      entry.psl++;\n    }\n  }\n\n  get(key) {\n    let idx = this._idealIndex(key);\n    let psl = 0;\n    while (true) {\n      const cur = this._slots[idx];\n      if (cur === null || psl > cur.psl) return undefined;\n      if (cur.key === key) return cur.value;\n      idx = (idx + 1) & this._mask;\n      psl++;\n    }\n  }\n\n  has(key) {\n    return this.get(key) !== undefined;\n  }\n\n  delete(key) {\n    let idx = this._idealIndex(key);\n    let psl = 0;\n    while (true) {\n      const cur = this._slots[idx];\n      if (cur === null || psl > cur.psl) return false;\n      if (cur.key === key) break;\n      idx = (idx + 1) & this._mask;\n      psl++;\n    }\n\n    this._slots[idx] = null;\n    this._size--;\n\n    let prev = idx;\n    let next = (idx + 1) & this._mask;\n    while (this._slots[next] !== null && this._slots[next].psl > 0) {\n      this._slots[prev] = this._slots[next];\n      this._slots[prev].psl--;\n      this._slots[next] = null;\n      prev = next;\n      next = (next + 1) & this._mask;\n    }\n    return true;\n  }\n\n  _resize(newCap) {\n    const old = this._slots;\n    this._capacity = newCap;\n    this._mask = newCap - 1;\n    this._size = 0;\n    this._slots = new Array(newCap).fill(null);\n    for (const entry of old) {\n      if (entry !== null) this.set(entry.key, entry.value);\n    }\n  }\n\n  maxPSL() {\n    let max = 0;\n    for (const s of this._slots) if (s && s.psl > max) max = s.psl;\n    return max;\n  }\n}\n\nmodule.exports = { RobinHoodHashMap, fnv1a32 };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const map = new RobinHoodHashMap(8, 0.75);\n\n  // Insert colliding & non-colliding keys\n  for (let i = 0; i < 200; i++) {\n    map.set('key:' + i, i * 10);\n  }\n  assert.equal(map.size, 200);\n  for (let i = 0; i < 200; i++) {\n    assert.equal(map.get('key:' + i), i * 10);\n  }\n  assert.equal(map.get('missing'), undefined);\n\n  // Update existing keys\n  map.set('key:50', 9999);\n  assert.equal(map.get('key:50'), 9999);\n  assert.equal(map.size, 200);\n\n  // Backward-shift deletion preserves PSL invariant & lookup correctness\n  for (let i = 0; i < 100; i += 2) {\n    assert.equal(map.delete('key:' + i), true);\n    assert.equal(map.delete('key:' + i), false);\n  }\n  assert.equal(map.size, 150);\n\n  for (let i = 0; i < 200; i++) {\n    if (i < 100 && i % 2 === 0) assert.equal(map.has('key:' + i), false);\n    else assert.equal(map.get('key:' + i), i === 50 ? 9999 : i * 10);\n  }\n\n  // Verify PSL invariant on every occupied slot\n  for (let idx = 0; idx < map._capacity; idx++) {\n    const s = map._slots[idx];\n    if (s) assert.equal(s.psl, map._psl(idx, map._idealIndex(s.key)));\n  }\n  return true;\n}\nrunTests();\n",
