    "code": "'use strict';\n/**\n * ============================================================================\n * Space-Efficient Bloom Filter & Fingerprint Cuckoo Filter (build-bloom-cuckoo-filter)\n * ============================================================================\n * Category: Hashing & Sketches\n * Difficulty: Advanced (~35 min)\n * Primary Curriculum Unit: bloom-filters-counting-xor\n * Related Units: robin-hood-cuckoo-hashing, universal-k-independent-hashing, count-min-sketch-heavy-hitters, hyperloglog-cardinality, case-rust-hashbrown-swisstable\n *\n * Summary:\n *   A Kirsch-Mitzenmacher double-hashed Bloom filter and a partial-key Cuckoo filter supporting dynamic deletions, fingerprint buckets, and false-positive rate telemetry.\n *\n * Key Engineering Highlights:\n *   1. Kirsch-Mitzenmacher double-hashing Bloom filter with Uint32Array bitset\n *   2. Partial-key Cuckoo filter computing alternate bucket via i2 = i1 ^ hash(fp)\n *   3. Dynamic deletion support with zero false negatives and bounded kick-out displacement\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Kirsch-Mitzenmacher Double Hashing: Implement `_bitPosition(item, i)` on `BloomFilter`. Using `h1 = hashA(String(item))` and `h2 = hashB(String(item))`, return `((h1 + Math.imul(i, h2)) >>> 0) % this.bitCount`.\n *   - Step 2: Packed Uint32Array Bitset Operations: Implement `add(item)` and `mightContain(item)` on `BloomFilter`. Bit `b` resides in 32-bit word `b >>> 5` at bit offset `b & 31`. A Bloom filter guarantees 0% false negatives.\n *   - Step 3: Partial-Key Cuckoo Hashing via XOR Symmetry: Implement `_indices(item)` on `CuckooFilter`. Because XOR is an involution ($x \\oplus y \\oplus y = x$), defining `i2 = (i1 ^ hashA(String(fp))) & mask` allows us to compute a displaced fingerprint’s alternate bucket from `(currentIdx, fp)` without storing the original key!\n *   - Step 4: Cuckoo Kick-Out Displacement & Safe Deletion: Implement `insert(item)` and `delete(item)` on `CuckooFilter`. 1. In `insert`: place `fp` in `buckets[i1]` or `buckets[i2]` if space exists; otherwise loop up to `maxKicks` times swapping `curFp` with a slot in `buckets[idx]` and jumping to `idx = _altIndex(idx, curFp)`. 2. In `delete`: remove one matching `fp` from `buckets[i1]` or `buckets[i2]`.\n * ============================================================================\n */\n\nfunction hashA(str) {\n  let h = 2166136261 >>> 0;\n  for (let i = 0; i < str.length; i++) {\n    h ^= str.charCodeAt(i);\n    h = Math.imul(h, 16777619) >>> 0;\n  }\n  return h >>> 0;\n}\n\nfunction hashB(str) {\n  let h = 0x9e3779b9 >>> 0;\n  for (let i = 0; i < str.length; i++) {\n    h ^= str.charCodeAt(i);\n    h = Math.imul(h, 0x85ebca6b) >>> 0;\n  }\n  return (h | 1) >>> 0;\n}\n\nclass BloomFilter {\n  constructor(expectedItems = 1024, falsePositiveRate = 0.01) {\n    const ln2 = Math.LN2;\n    this.bitCount = Math.max(64, Math.ceil(-(expectedItems * Math.log(falsePositiveRate)) / (ln2 * ln2)));\n    this.k = Math.max(1, Math.round((this.bitCount / expectedItems) * ln2));\n    this.words = new Uint32Array(Math.ceil(this.bitCount / 32));\n  }\n\n  _bitPosition(item, i) {\n    const s = String(item);\n    const h1 = hashA(s);\n    const h2 = hashB(s);\n    return ((h1 + Math.imul(i, h2)) >>> 0) % this.bitCount;\n  }\n\n  add(item) {\n    for (let i = 0; i < this.k; i++) {\n      const bit = this._bitPosition(item, i);\n      this.words[bit >>> 5] |= (1 << (bit & 31));\n    }\n  }\n\n  mightContain(item) {\n    for (let i = 0; i < this.k; i++) {\n      const bit = this._bitPosition(item, i);\n      if ((this.words[bit >>> 5] & (1 << (bit & 31))) === 0) return false;\n    }\n    return true;\n  }\n}\n\nclass CuckooFilter {\n  constructor(bucketCount = 64, bucketSize = 4, maxKicks = 256) {\n    let cap = 1;\n    while (cap < Math.max(8, bucketCount)) cap <<= 1;\n    this.bucketCount = cap;\n    this.mask = cap - 1;\n    this.bucketSize = bucketSize;\n    this.maxKicks = maxKicks;\n    this.buckets = Array.from({ length: cap }, () => []);\n    this.size = 0;\n  }\n\n  _fingerprint(item) {\n    const fp = hashB(String(item)) & 0xffff;\n    return fp === 0 ? 1 : fp;\n  }\n\n  _altIndex(idx, fp) {\n    return (idx ^ hashA(String(fp))) & this.mask;\n  }\n\n  _indices(item) {\n    const s = String(item);\n    const fp = this._fingerprint(s);\n    const i1 = hashA(s) & this.mask;\n    const i2 = this._altIndex(i1, fp);\n    return [i1, i2, fp];\n  }\n\n  insert(item) {\n    const [i1, i2, fp] = this._indices(item);\n    if (this.buckets[i1].length < this.bucketSize) {\n      this.buckets[i1].push(fp);\n      this.size++;\n      return true;\n    }\n    if (this.buckets[i2].length < this.bucketSize) {\n      this.buckets[i2].push(fp);\n      this.size++;\n      return true;\n    }\n    let idx = i1;\n    let curFp = fp;\n    for (let kick = 0; kick < this.maxKicks; kick++) {\n      const slot = kick % this.bucketSize;\n      const evicted = this.buckets[idx][slot];\n      this.buckets[idx][slot] = curFp;\n      curFp = evicted;\n      idx = this._altIndex(idx, curFp);\n      if (this.buckets[idx].length < this.bucketSize) {\n        this.buckets[idx].push(curFp);\n        this.size++;\n        return true;\n      }\n    }\n    return false;\n  }\n\n  contains(item) {\n    const [i1, i2, fp] = this._indices(item);\n    return this.buckets[i1].includes(fp) || this.buckets[i2].includes(fp);\n  }\n\n  delete(item) {\n    const [i1, i2, fp] = this._indices(item);\n    const pos1 = this.buckets[i1].indexOf(fp);\n    if (pos1 !== -1) {\n      this.buckets[i1].splice(pos1, 1);\n      this.size--;\n      return true;\n    }\n    const pos2 = this.buckets[i2].indexOf(fp);\n    if (pos2 !== -1) {\n      this.buckets[i2].splice(pos2, 1);\n      this.size--;\n      return true;\n    }\n    return false;\n  }\n}\n\nmodule.exports = { BloomFilter, CuckooFilter, hashA, hashB };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n\n  // Bloom Filter: zero false negatives & bounded false positive rate\n  const bf = new BloomFilter(500, 0.02);\n  for (let i = 0; i < 500; i++) bf.add('item-' + i);\n  for (let i = 0; i < 500; i++) assert.equal(bf.mightContain('item-' + i), true);\n\n  let fpCount = 0;\n  for (let i = 1000; i < 2000; i++) {\n    if (bf.mightContain('item-' + i)) fpCount++;\n  }\n  assert.ok(fpCount < 60, 'False positive rate well within theoretical bound');\n\n  // Cuckoo Filter: XOR involutory property, insertion, lookup, and deletion\n  const cf = new CuckooFilter(128, 4);\n  for (let i = 0; i < 300; i++) {\n    assert.equal(cf.insert('key-' + i), true);\n  }\n  assert.equal(cf.size, 300);\n  for (let i = 0; i < 300; i++) {\n    assert.equal(cf.contains('key-' + i), true);\n  }\n  for (let i = 0; i < 150; i++) {\n    assert.equal(cf.delete('key-' + i), true);\n    assert.equal(cf.contains('key-' + i), false);\n  }\n  for (let i = 150; i < 300; i++) {\n    assert.equal(cf.contains('key-' + i), true);\n  }\n  return true;\n}\nrunTests();\n",
