    "code": "'use strict';\n/**\n * ============================================================================\n * Indexed d-ary Priority Queue with O(log_d N) Decrease-Key (build-indexed-d-ary-priority-queue)\n * ============================================================================\n * Category: Trees & Priority Queues\n * Difficulty: Intermediate (~30 min)\n * Primary Curriculum Unit: build-indexed-d-ary-priority-queue\n * Related Units: binary-d-ary-heaps, dijkstra-relaxation-invariants, case-timer-wheels-vs-heaps, mergeable-heaps-binomial-fibonacci, two-heaps-k-way-merge-patterns\n *\n * Summary:\n *   Sedgewick’s Indexed d-ary Min-Priority Queue maintaining bidirectional heap/key position maps for O(1) lookup and O(log_d N) decreaseKey and arbitrary deletion.\n *\n * Key Engineering Highlights:\n *   1. Configurable arity d (default d=4) reducing siftUp height by log2(d) and grouping children into one cache line\n *   2. Bidirectional index maps pq[] and qp[] supporting O(1) contains(id) and O(log_d N) updateKey/delete\n *   3. Zero duplicate heap entries during Dijkstra and Prim edge relaxations\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: d-ary Heap Geometry & Bidirectional Swap: Implement `_parent(pos)`, `_firstChild(pos)`, and `_swap(i, j)`. In a 0-indexed $d$-ary heap: - `_parent(pos) = Math.floor((pos - 1) / this.d)` - `_firstChild(pos) = pos * this.d + 1` - `this.qp[this.pq[pos]] === pos` must hold for every `0 <= pos < this._size`.\n *   - Step 2: d-ary _siftUp and _siftDown: Implement `_siftUp(pos)` and `_siftDown(pos)`. In `_siftDown(pos)`, inspect children `first = pos * d + 1` through `Math.min(size - 1, first + d - 1)`, find `minChild`, and swap if `_less(minChild, pos)`.\n *   - Step 3: Indexed Insert and popMin: Implement `insert(id, priority)` and `popMin()`. In `popMin()`, swap root `0` with `size - 1`, decrement `_size`, mark `qp[minId] = -1`, clear `keys[minId] = undefined`, and `_siftDown(0)` if non-empty.\n *   - Step 4: O(log_d N) updateKey and Arbitrary Deletion: Implement `updateKey(id, newPriority)` and `delete(id)`. Because `pos = this.qp[id]` gives the exact heap slot in $O(1)$, updating or deleting an arbitrary key requires only `_siftUp(pos)` and `_siftDown(pos)`.\n * ============================================================================\n */\n\nclass IndexedDaryMinPQ {\n  constructor(maxKeys = 1024, d = 4, cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)) {\n    if (d < 2) throw new RangeError('Arity d must be >= 2');\n    this.maxKeys = maxKeys;\n    this.d = d;\n    this.cmp = cmp;\n    this._size = 0;\n    this.pq = new Int32Array(maxKeys);\n    this.qp = new Int32Array(maxKeys).fill(-1);\n    this.keys = new Array(maxKeys).fill(undefined);\n  }\n\n  get size() { return this._size; }\n  get isEmpty() { return this._size === 0; }\n  contains(id) { return id >= 0 && id < this.maxKeys && this.qp[id] !== -1; }\n\n  _parent(pos) {\n    return Math.floor((pos - 1) / this.d);\n  }\n\n  _firstChild(pos) {\n    return pos * this.d + 1;\n  }\n\n  _less(i, j) {\n    return this.cmp(this.keys[this.pq[i]], this.keys[this.pq[j]]) < 0;\n  }\n\n  _swap(i, j) {\n    const idI = this.pq[i];\n    const idJ = this.pq[j];\n    this.pq[i] = idJ;\n    this.pq[j] = idI;\n    this.qp[idJ] = i;\n    this.qp[idI] = j;\n  }\n\n  _siftUp(pos) {\n    while (pos > 0) {\n      const p = this._parent(pos);\n      if (!this._less(pos, p)) break;\n      this._swap(pos, p);\n      pos = p;\n    }\n  }\n\n  _siftDown(pos) {\n    while (true) {\n      const first = this._firstChild(pos);\n      if (first >= this._size) break;\n      const last = Math.min(this._size - 1, first + this.d - 1);\n      let minChild = first;\n      for (let c = first + 1; c <= last; c++) {\n        if (this._less(c, minChild)) minChild = c;\n      }\n      if (!this._less(minChild, pos)) break;\n      this._swap(pos, minChild);\n      pos = minChild;\n    }\n  }\n\n  insert(id, priority) {\n    if (this.contains(id)) {\n      this.updateKey(id, priority);\n      return;\n    }\n    const pos = this._size++;\n    this.pq[pos] = id;\n    this.qp[id] = pos;\n    this.keys[id] = priority;\n    this._siftUp(pos);\n  }\n\n  peekMin() {\n    if (this._size === 0) return undefined;\n    const id = this.pq[0];\n    return { id, priority: this.keys[id] };\n  }\n\n  popMin() {\n    if (this._size === 0) return undefined;\n    const minId = this.pq[0];\n    const minPriority = this.keys[minId];\n    this._swap(0, this._size - 1);\n    this._size--;\n    this.qp[minId] = -1;\n    this.keys[minId] = undefined;\n    if (this._size > 0) this._siftDown(0);\n    return { id: minId, priority: minPriority };\n  }\n\n  updateKey(id, newPriority) {\n    if (!this.contains(id)) throw new Error('Key not in PQ');\n    this.keys[id] = newPriority;\n    const pos = this.qp[id];\n    this._siftUp(pos);\n    this._siftDown(pos);\n  }\n\n  decreaseKey(id, newPriority) {\n    if (!this.contains(id)) throw new Error('Key not in PQ');\n    if (this.cmp(newPriority, this.keys[id]) > 0) throw new Error('New priority is greater');\n    this.keys[id] = newPriority;\n    this._siftUp(this.qp[id]);\n  }\n\n  delete(id) {\n    if (!this.contains(id)) return false;\n    const pos = this.qp[id];\n    this._swap(pos, this._size - 1);\n    this._size--;\n    this.qp[id] = -1;\n    this.keys[id] = undefined;\n    if (pos < this._size) {\n      this._siftUp(pos);\n      this._siftDown(pos);\n    }\n    return true;\n  }\n}\n\nmodule.exports = { IndexedDaryMinPQ };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = require('node:assert/strict');\n  const pq = new IndexedDaryMinPQ(100, 4);\n\n  pq.insert(5, 50);\n  pq.insert(2, 20);\n  pq.insert(8, 80);\n  pq.insert(1, 10);\n  pq.insert(9, 90);\n  pq.insert(3, 30);\n\n  assert.equal(pq.size, 6);\n  assert.deepEqual(pq.peekMin(), { id: 1, priority: 10 });\n\n  // Decrease key of id=8 from 80 to 5\n  pq.decreaseKey(8, 5);\n  assert.deepEqual(pq.peekMin(), { id: 8, priority: 5 });\n\n  // Delete arbitrary internal key id=2\n  assert.equal(pq.delete(2), true);\n  assert.equal(pq.contains(2), false);\n\n  // Increase key of id=1 from 10 to 60 via updateKey\n  pq.updateKey(1, 60);\n\n  const popped = [];\n  while (!pq.isEmpty) popped.push(pq.popMin());\n  assert.deepEqual(popped.map(x => x.id), [8, 3, 5, 1, 9]);\n  assert.deepEqual(popped.map(x => x.priority), [5, 30, 50, 60, 90]);\n  return true;\n}\nrunTests();\n",
