      "test.js": "'use strict';\n\nconst exported = require('./index.js');\nObject.assign(globalThis, exported);\n\n'use strict';\n\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const tree = new OrderStatisticLLRB();\n  const keys = [50, 20, 80, 10, 30, 70, 90, 25, 35, 65, 85, 5, 15, 95, 60];\n  for (const k of keys) {\n    tree.put(k, 'v' + k);\n    assert(tree.verifyInvariants(), 'LLRB invariants after inserting ' + k);\n  }\n  assert(tree.size === keys.length, 'tree size should match keys count');\n\n  const sorted = [...keys].sort((a, b) => a - b);\n  for (let i = 0; i < sorted.length; i++) {\n    assert(tree.select(i) === sorted[i], 'select(' + i + ') should be ' + sorted[i]);\n    assert(tree.rank(sorted[i]) === i, 'rank(' + sorted[i] + ') should be ' + i);\n  }\n  assert(tree.rank(0) === 0, 'rank below min');\n  assert(tree.rank(1000) === sorted.length, 'rank above max');\n  assert(tree.rangeCount(20, 70) === 8, 'rangeCount [20, 70]');\n\n  // Stress test sequential inserts + deletes (worst case for unbalanced BST)\n  const big = new OrderStatisticLLRB();\n  for (let i = 1; i <= 200; i++) big.put(i, i * 10);\n  assert(big.verifyInvariants(), 'invariants after 200 sequential inserts');\n  for (let i = 1; i <= 200; i += 2) {\n    assert(big.delete(i) === true, 'delete odd ' + i);\n    assert(big.verifyInvariants(), 'invariants after deleting ' + i);\n  }\n  assert(big.size === 100, 'size 100 after deleting odds');\n  for (let i = 0; i < 100; i++) {\n    assert(big.select(i) === (i + 1) * 2, 'select after odd deletion');\n    assert(big.rank((i + 1) * 2) === i, 'rank after odd deletion');\n  }\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\nif (require.main === module) {\n  const res = runTests();\n  console.log('All tests passed:', res);\n}\n\n",
