    "code": "'use strict';\n/**\n * ============================================================================\n * Aho-Corasick Multi-Pattern Automaton Scanner (build-aho-corasick-scanner)\n * ============================================================================\n * Category: Strings & Automata\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-aho-corasick-scanner\n * Related Units: aho-corasick-trie-automaton, tries-radix-trees-patricia, kmp-prefix-function-automaton, z-algorithm-linear-box, dfs-edge-classification-timestamps\n *\n * Summary:\n *   An Aho-Corasick multi-pattern string matching automaton with BFS failure links, dictionary output shortcuts, and deterministic O(|T| + z) stream scanning.\n *\n * Key Engineering Highlights:\n *   1. Trie construction with BFS failure-link synthesis generalizing KMP to dictionaries\n *   2. Dictionary suffix shortcuts (outputLinks) avoiding O(m) failure-chain traversal on sparse matches\n *   3. Deterministic DFA transition table compilation guaranteeing O(1) per-character text scanning\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Keyword Trie Insertion: Implement `addPattern(pattern)` to insert each pattern character-by-character into `this._nodes` and record the pattern index in the terminal node's `outputs` list.\n *   - Step 2: BFS Failure Links & Dictionary Output Links: Implement `compile()` using level-order BFS so every node `v` (child of `u` via `ch`) resolves `fail[v]` from `fail[u]` and sets `outputLink[v]` to the nearest proper suffix state that is a dictionary word.\n *   - Step 3: Amortized O(1) Automaton Transitions: Implement `_step(state, ch)` to climb failure links when a character transition is absent.\n *   - Step 4: Multi-Pattern Stream Harvesting: Implement `search(text)` to step through `text` once and follow `outputLink` pointers to emit all overlapping pattern matches in $O(|T| + z)$ time.\n * ============================================================================\n */\n\nclass AhoCorasickNode {\n  constructor() {\n    this.next = new Map();\n    this.fail = 0;\n    this.outputLink = 0;\n    this.outputs = [];\n  }\n}\n\nclass AhoCorasickScanner {\n  constructor(patterns = []) {\n    this._nodes = [new AhoCorasickNode()];\n    this._patterns = [];\n    this._compiled = false;\n    for (const p of patterns) this.addPattern(p);\n    if (patterns.length > 0) this.compile();\n  }\n\n  addPattern(pattern) {\n    if (!pattern || pattern.length === 0) return -1;\n    this._compiled = false;\n    const id = this._patterns.length;\n    this._patterns.push(pattern);\n    let u = 0;\n    for (let i = 0; i < pattern.length; i++) {\n      const ch = pattern[i];\n      if (!this._nodes[u].next.has(ch)) {\n        this._nodes[u].next.set(ch, this._nodes.length);\n        this._nodes.push(new AhoCorasickNode());\n      }\n      u = this._nodes[u].next.get(ch);\n    }\n    this._nodes[u].outputs.push(id);\n    return id;\n  }\n\n  compile() {\n    const queue = [];\n    for (const [, v] of this._nodes[0].next) {\n      this._nodes[v].fail = 0;\n      this._nodes[v].outputLink = 0;\n      queue.push(v);\n    }\n    let head = 0;\n    while (head < queue.length) {\n      const u = queue[head++];\n      for (const [ch, v] of this._nodes[u].next) {\n        queue.push(v);\n        let f = this._nodes[u].fail;\n        while (f !== 0 && !this._nodes[f].next.has(ch)) {\n          f = this._nodes[f].fail;\n        }\n        const failTarget = this._nodes[f].next.get(ch) || 0;\n        this._nodes[v].fail = failTarget === v ? 0 : failTarget;\n        const ft = this._nodes[v].fail;\n        this._nodes[v].outputLink = this._nodes[ft].outputs.length > 0\n          ? ft\n          : this._nodes[ft].outputLink;\n      }\n    }\n    this._compiled = true;\n  }\n\n  _step(state, ch) {\n    let u = state;\n    while (u !== 0 && !this._nodes[u].next.has(ch)) {\n      u = this._nodes[u].fail;\n    }\n    return this._nodes[u].next.get(ch) || 0;\n  }\n\n  search(text) {\n    if (!this._compiled) this.compile();\n    const matches = [];\n    let state = 0;\n    for (let i = 0; i < text.length; i++) {\n      state = this._step(state, text[i]);\n      for (let temp = state; temp !== 0; temp = this._nodes[temp].outputLink) {\n        for (const patId of this._nodes[temp].outputs) {\n          const pat = this._patterns[patId];\n          matches.push({\n            pattern: pat,\n            patternId: patId,\n            start: i - pat.length + 1,\n            end: i\n          });\n        }\n      }\n    }\n    return matches;\n  }\n\n  countMatches(text) {\n    return this.search(text).length;\n  }\n}\n\nmodule.exports = { AhoCorasickScanner };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Classic Aho-Corasick paper benchmark: [\"he\", \"she\", \"his\", \"hers\"] in \"ushers\"\n  const scanner = new AhoCorasickScanner(['he', 'she', 'his', 'hers']);\n  const hits = scanner.search('ushers');\n  const foundPatterns = hits.map(h => `${h.pattern}@${h.start}`).sort();\n  assert(\n    JSON.stringify(foundPatterns) === JSON.stringify(['he@2', 'hers@2', 'she@1']),\n    'classic ushers test: ' + JSON.stringify(foundPatterns)\n  );\n\n  // Overlapping nested substrings\n  const dna = new AhoCorasickScanner(['A', 'AA', 'AAA', 'ABA', 'B']);\n  const text = 'AAABAAA';\n  const actual = dna.search(text);\n  // Brute force verification\n  const expected = [];\n  for (const pat of ['A', 'AA', 'AAA', 'ABA', 'B']) {\n    for (let i = 0; i + pat.length <= text.length; i++) {\n      if (text.slice(i, i + pat.length) === pat) {\n        expected.push(`${pat}@${i}`);\n      }\n    }\n  }\n  const actualKeys = actual.map(m => `${m.pattern}@${m.start}`).sort();\n  expected.sort();\n  assert(JSON.stringify(actualKeys) === JSON.stringify(expected), 'overlapping DNA matches');\n\n  return { passed: 4, total: 4 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\n// Execute self-test suite when evaluated directly\nrunTests();\n",
