    "code": "'use strict';\n/**\n * ============================================================================\n * Tarjan Strongly Connected Components & Linear-Time 2-SAT Solver (build-tarjan-scc-2sat-solver)\n * ============================================================================\n * Category: Graph Algorithms\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-tarjan-scc-2sat-solver\n * Related Units: scc-tarjan-kosaraju-2sat, dfs-edge-classification-timestamps, topological-sort-kahn-dfs, bridges-articulation-biconnected, branch-and-bound-admissible-bounds\n *\n * Summary:\n *   Tarjan single-pass low-link Strongly Connected Components (SCC) engine and a linear-time 2-SAT boolean satisfiability solver over implication graphs.\n *\n * Key Engineering Highlights:\n *   1. Single-pass Tarjan DFS computing discovery times, low-link values, and reverse-topological SCC IDs\n *   2. Implication graph encoding (a v b) as (~a -> b) and (~b -> a) over 2n literal vertices\n *   3. Linear-time O(V + E) 2-SAT satisfiability check and truth assignment extraction\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Discovery & Low-Link Invariant Maintenance: In `tarjanSCC`, track `disc[u]` and `low[u]`. On tree edges update `low[u] = Math.min(low[u], low[v])`; on back/cross edges to vertices currently `onStack` update `low[u] = Math.min(low[u], disc[v])`.\n *   - Step 2: SCC Root Identification & Stack Popping: When `low[u] === disc[u]`, `u` is the entry root of an SCC. Pop vertices from the active stack until `u` is popped; notice that components are emitted in **reverse topological order**.\n *   - Step 3: 2-SAT Implication Graph Construction: Encode boolean variable $x_i$ as vertex $2i$ and $\\lnot x_i$ as $2i+1$ (so negation is `node ^ 1`). Every clause $(A \\lor B)$ adds directed edges $(\\lnot A \\to B)$ and $(\\lnot B \\to A)$.\n *   - Step 4: Linear-Time Satisfiability & Truth Assignment: Run `tarjanSCC` on the $2n$-vertex implication graph. The formula is satisfiable iff `compId[2*i] !== compId[2*i+1]` for all $i$, with `assignment[i] = compId[2*i] < compId[2*i+1]`.\n * ============================================================================\n */\n\nfunction tarjanSCC(numVertices, adj) {\n  const disc = new Int32Array(numVertices).fill(-1);\n  const low = new Int32Array(numVertices).fill(-1);\n  const onStack = new Uint8Array(numVertices);\n  const compId = new Int32Array(numVertices).fill(-1);\n  const stack = [];\n  const components = [];\n  let timer = 0;\n\n  const dfs = (u) => {\n    disc[u] = low[u] = timer++;\n    stack.push(u);\n    onStack[u] = 1;\n\n    const neighbors = adj[u] || [];\n    for (let i = 0; i < neighbors.length; i++) {\n      const v = neighbors[i];\n      if (disc[v] === -1) {\n        dfs(v);\n        if (low[v] < low[u]) low[u] = low[v];\n      } else if (onStack[v]) {\n        if (disc[v] < low[u]) low[u] = disc[v];\n      }\n    }\n\n    if (low[u] === disc[u]) {\n      const scc = [];\n      const cid = components.length;\n      while (true) {\n        const w = stack.pop();\n        onStack[w] = 0;\n        compId[w] = cid;\n        scc.push(w);\n        if (w === u) break;\n      }\n      components.push(scc);\n    }\n  };\n\n  for (let i = 0; i < numVertices; i++) {\n    if (disc[i] === -1) dfs(i);\n  }\n\n  return { count: components.length, compId, components };\n}\n\nclass TwoSatSolver {\n  constructor(numVars) {\n    this.n = numVars;\n    this.adj = Array.from({ length: 2 * numVars }, () => []);\n  }\n\n  static _litNode(varIdx, isTrue) {\n    return isTrue ? 2 * varIdx : 2 * varIdx + 1;\n  }\n\n  static _negNode(node) {\n    return node ^ 1;\n  }\n\n  addClause(varA, isTrueA, varB, isTrueB) {\n    const a = TwoSatSolver._litNode(varA, isTrueA);\n    const b = TwoSatSolver._litNode(varB, isTrueB);\n    this.adj[TwoSatSolver._negNode(a)].push(b);\n    this.adj[TwoSatSolver._negNode(b)].push(a);\n  }\n\n  addImplication(varA, isTrueA, varB, isTrueB) {\n    this.addClause(varA, !isTrueA, varB, isTrueB);\n  }\n\n  addXor(varA, varB) {\n    this.addClause(varA, true, varB, true);\n    this.addClause(varA, false, varB, false);\n  }\n\n  solve() {\n    const { compId } = tarjanSCC(2 * this.n, this.adj);\n    const assignment = new Array(this.n);\n    for (let i = 0; i < this.n; i++) {\n      if (compId[2 * i] === compId[2 * i + 1]) {\n        return { satisfiable: false, assignment: null };\n      }\n      // Tarjan pops sink SCCs first, so smaller compId means later in topological order\n      assignment[i] = compId[2 * i] < compId[2 * i + 1];\n    }\n    return { satisfiable: true, assignment };\n  }\n}\n\nmodule.exports = { tarjanSCC, TwoSatSolver };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Directed graph with 3 SCCs: {0,1,2}, {3}, {4,5}\n  const adj = [\n    [1],       // 0 -> 1\n    [2],       // 1 -> 2\n    [0, 3],    // 2 -> 0, 3\n    [4],       // 3 -> 4\n    [5],       // 4 -> 5\n    [4]        // 5 -> 4\n  ];\n  const sccRes = tarjanSCC(6, adj);\n  assert(sccRes.count === 3, 'should find 3 SCCs');\n  assert(sccRes.compId[0] === sccRes.compId[1] && sccRes.compId[1] === sccRes.compId[2], '{0,1,2} in same SCC');\n  assert(sccRes.compId[4] === sccRes.compId[5], '{4,5} in same SCC');\n  assert(sccRes.compId[4] < sccRes.compId[3] && sccRes.compId[3] < sccRes.compId[0], 'reverse topological order');\n\n  // Satisfiable 2-SAT instance\n  const sat = new TwoSatSolver(3);\n  const clauses = [\n    [0, true, 1, true],   // x0 v x1\n    [0, false, 1, true],  // ~x0 v x1  (forces x1 = true)\n    [1, false, 2, false], // ~x1 v ~x2 (forces x2 = false)\n    [0, true, 2, true]    // x0 v x2   (forces x0 = true)\n  ];\n  for (const c of clauses) sat.addClause(...c);\n  const res = sat.solve();\n  assert(res.satisfiable === true, '2-SAT instance should be satisfiable');\n  assert(JSON.stringify(res.assignment) === JSON.stringify([true, true, false]), 'unique assignment [T, T, F]');\n\n  // Unsatisfiable 2-SAT instance: (x0 v x0) & (~x0 v ~x0)\n  const unsat = new TwoSatSolver(1);\n  unsat.addClause(0, true, 0, true);\n  unsat.addClause(0, false, 0, false);\n  assert(unsat.solve().satisfiable === false, 'contradictory 2-SAT should be unsatisfiable');\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\n// Execute self-test suite when evaluated directly\nrunTests();\n",
