    "code": "'use strict';\n/**\n * ============================================================================\n * Hirschberg O(n)-Space Divide-and-Conquer Sequence Alignment & Diff (build-hirschberg-linear-space-diff)\n * ============================================================================\n * Category: Dynamic Programming & Divide-and-Conquer\n * Difficulty: Advanced (~50 min)\n * Primary Curriculum Unit: build-hirschberg-linear-space-diff\n * Related Units: sequence-dp-lcs-levenshtein, dp-optimal-substructure-dag, mergesort-bottom-up-inversions, recurrence-relations-master-theorem, z-algorithm-linear-box\n *\n * Summary:\n *   Dan Hirschberg's divide-and-conquer sequence alignment and edit-script diff engine that recovers the full optimal edit transcript in O(nm) time and strictly linear O(n + m) memory.\n *\n * Key Engineering Highlights:\n *   1. Two-row rolling DP computing forward prefix costs and backward suffix costs in O(min(n, m)) memory\n *   2. Optimal midpoint split k* = argmin_k (fwd[k] + bwd[m - k]) on the middle row i = floor(n/2)\n *   3. Master-Theorem geometric work series T(n,m) <= 2 n m achieving O(nm) time in O(n + m) total space\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Two-Row Space-Optimized Forward & Reverse DP: Implement `_dpRow(a, b, reverse)` using only two `Int32Array(m + 1)` buffers (`prev` and `curr`). When `reverse === true`, scan `a` and `b` from right to left to compute suffix edit distances.\n *   - Step 2: Base-Case Alignment Transcript: Implement `_alignBase(a, b)` for when `|a| <= 1` or `|b| <= 1`, where the DP matrix has size $O(n + m)$ and can be backtracked directly.\n *   - Step 3: Optimal Midpoint Split Discovery: Split `a` at `mid = n >> 1`, run forward DP on `a[0..mid)` and reverse DP on `a[mid..n)`, and find the split index $k^* = \\arg\\min_k (\\text{scoreL}[k] + \\text{scoreR}[m - k])$.\n *   - Step 4: Divide-and-Conquer Transcript Concatenation: Recurse on `(a[0..mid), b[0..k*])` and `(a[mid..n), b[k*..m])` and concatenate their edit scripts.\n * ============================================================================\n */\n\nclass HirschbergDiff {\n  constructor({ matchCost = 0, subCost = 1, insCost = 1, delCost = 1 } = {}) {\n    this.matchCost = matchCost;\n    this.subCost = subCost;\n    this.insCost = insCost;\n    this.delCost = delCost;\n  }\n\n  _dpRow(a, b, reverse = false) {\n    const n = a.length, m = b.length;\n    let prev = new Int32Array(m + 1);\n    let curr = new Int32Array(m + 1);\n    for (let j = 0; j <= m; j++) prev[j] = j * this.insCost;\n\n    for (let i = 1; i <= n; i++) {\n      const ca = reverse ? a[n - i] : a[i - 1];\n      curr[0] = i * this.delCost;\n      for (let j = 1; j <= m; j++) {\n        const cb = reverse ? b[m - j] : b[j - 1];\n        const stepDiag = prev[j - 1] + (ca === cb ? this.matchCost : this.subCost);\n        const stepDel = prev[j] + this.delCost;\n        const stepIns = curr[j - 1] + this.insCost;\n        curr[j] = Math.min(stepDiag, stepDel, stepIns);\n      }\n      const tmp = prev; prev = curr; curr = tmp;\n    }\n    return prev;\n  }\n\n  _alignBase(a, b) {\n    const n = a.length, m = b.length;\n    const dp = Array.from({ length: n + 1 }, () => new Int32Array(m + 1));\n    for (let i = 0; i <= n; i++) dp[i][0] = i * this.delCost;\n    for (let j = 0; j <= m; j++) dp[0][j] = j * this.insCost;\n\n    for (let i = 1; i <= n; i++) {\n      for (let j = 1; j <= m; j++) {\n        const cost = a[i - 1] === b[j - 1] ? this.matchCost : this.subCost;\n        dp[i][j] = Math.min(\n          dp[i - 1][j - 1] + cost,\n          dp[i - 1][j] + this.delCost,\n          dp[i][j - 1] + this.insCost\n        );\n      }\n    }\n\n    const ops = [];\n    let i = n, j = m;\n    while (i > 0 || j > 0) {\n      if (i > 0 && j > 0) {\n        const isMatch = a[i - 1] === b[j - 1];\n        const cost = isMatch ? this.matchCost : this.subCost;\n        if (dp[i][j] === dp[i - 1][j - 1] + cost) {\n          ops.push({ op: isMatch ? 'MATCH' : 'SUB', aChar: a[i - 1], bChar: b[j - 1] });\n          i--; j--;\n          continue;\n        }\n      }\n      if (i > 0 && dp[i][j] === dp[i - 1][j] + this.delCost) {\n        ops.push({ op: 'DEL', aChar: a[i - 1], bChar: null });\n        i--;\n      } else {\n        ops.push({ op: 'INS', aChar: null, bChar: b[j - 1] });\n        j--;\n      }\n    }\n    ops.reverse();\n    return ops;\n  }\n\n  _hirschberg(a, b) {\n    const n = a.length, m = b.length;\n    if (n <= 1 || m <= 1) return this._alignBase(a, b);\n\n    const mid = n >> 1;\n    const aLeft = a.slice(0, mid);\n    const aRight = a.slice(mid);\n\n    const scoreL = this._dpRow(aLeft, b, false);\n    const scoreR = this._dpRow(aRight, b, true);\n\n    let bestK = 0;\n    let bestCost = Infinity;\n    for (let k = 0; k <= m; k++) {\n      const total = scoreL[k] + scoreR[m - k];\n      if (total < bestCost) {\n        bestCost = total;\n        bestK = k;\n      }\n    }\n\n    const leftOps = this._hirschberg(aLeft, b.slice(0, bestK));\n    const rightOps = this._hirschberg(aRight, b.slice(bestK));\n    return leftOps.concat(rightOps);\n  }\n\n  align(a, b) {\n    const operations = this._hirschberg(String(a), String(b));\n    let distance = 0;\n    for (const step of operations) {\n      if (step.op === 'MATCH') distance += this.matchCost;\n      else if (step.op === 'SUB') distance += this.subCost;\n      else if (step.op === 'INS') distance += this.insCost;\n      else if (step.op === 'DEL') distance += this.delCost;\n    }\n    return { distance, operations };\n  }\n}\n\nmodule.exports = { HirschbergDiff };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  const diff = new HirschbergDiff();\n\n  const verifyPair = (a, b, expectedDist) => {\n    const { distance, operations } = diff.align(a, b);\n    assert(distance === expectedDist, `distance(${a}, ${b}) expected ${expectedDist}, got ${distance}`);\n    // Reconstruct both strings from edit transcript\n    const recA = operations.filter(o => o.aChar !== null).map(o => o.aChar).join('');\n    const recB = operations.filter(o => o.bChar !== null).map(o => o.bChar).join('');\n    assert(recA === a, 'reconstructed A matches original');\n    assert(recB === b, 'reconstructed B matches original');\n  };\n\n  verifyPair('kitten', 'sitting', 3);\n  verifyPair('intention', 'execution', 5);\n  verifyPair('AGTACGCA', 'TATGC', 4);\n  verifyPair('', 'abcde', 5);\n  verifyPair('abcde', '', 5);\n\n  return { passed: 5, total: 5 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\n// Execute self-test suite when evaluated directly\nrunTests();\n",
