    "code": "'use strict';\n/**\n * ============================================================================\n * Li Chao Segment Tree & Monotonic Convex Hull Trick DP Engine (build-li-chao-convex-hull-dp)\n * ============================================================================\n * Category: Dynamic Programming & Divide-and-Conquer\n * Difficulty: Advanced (~50 min)\n * Primary Curriculum Unit: build-li-chao-convex-hull-dp\n * Related Units: convex-hull-trick-li-chao-tree, segment-trees-bottom-up-monoids, dynamic-persistent-segment-trees, monotonic-deque-sliding-extrema, convex-hull-graham-andrew\n *\n * Summary:\n *   A dynamically allocated Li Chao Segment Tree and a Monotonic Convex Hull Trick queue for optimizing O(n^2) dynamic programming recurrences of the form dp[i] = min_j (m_j * x_i + b_j) to O(n log X) and O(n).\n *\n * Key Engineering Highlights:\n *   1. Dynamic Li Chao Segment Tree handling arbitrary (non-monotonic) slopes and query points in O(log X)\n *   2. Single-intersection line dominance invariant recursing into at most one child per level\n *   3. O(n) Monotonic Deque Convex Hull Trick for sorted slopes and queries\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Midpoint Dominance Swap in Li Chao Tree: At interval $[l, r]$ with midpoint $mid$, evaluate both `newLine` and `node.line` at $l$ and $mid$. If `newLine` is strictly smaller at $mid$, swap `node.line` and `newLine` so `node.line` is always the winner at $mid$.\n *   - Step 2: Single-Branch Intersection Recursion: Because two distinct lines intersect at most once, the losing line at $mid$ can beat `node.line` on **at most one half** of $[l, r]$ (the left half iff `leftBetter !== midBetter`). Recurse only into that half in $O(\\log X)$ time.\n *   - Step 3: Root-to-Leaf Envelope Evaluation: Implement `query(x)` by taking the minimum of `node.line.eval(x)` across all $O(\\log X)$ nodes on the path covering $x$.\n *   - Step 4: O(n) Monotonic Deque Convex Hull Trick: When slopes $m_j$ decrease monotonically and queries $x_i$ increase monotonically, maintain the lower envelope in a deque using cross-multiplied intersection comparisons and a monotone pointer.\n * ============================================================================\n */\n\nclass Line {\n  constructor(m = 0, b = Infinity) {\n    this.m = m;\n    this.b = b;\n  }\n  eval(x) {\n    return this.m * x + this.b;\n  }\n}\n\nclass LiChaoNode {\n  constructor(line = new Line()) {\n    this.line = line;\n    this.left = null;\n    this.right = null;\n  }\n}\n\nclass LiChaoTree {\n  constructor(minX = -1000000, maxX = 1000000) {\n    this.minX = minX;\n    this.maxX = maxX;\n    this.root = null;\n  }\n\n  addLine(m, b) {\n    this.root = this._insert(this.root, this.minX, this.maxX, new Line(m, b));\n  }\n\n  _insert(node, l, r, newLine) {\n    if (!node) return new LiChaoNode(newLine);\n    const mid = Math.floor((l + r) / 2);\n    const leftBetter = newLine.eval(l) < node.line.eval(l);\n    const midBetter = newLine.eval(mid) < node.line.eval(mid);\n\n    if (midBetter) {\n      const tmp = node.line;\n      node.line = newLine;\n      newLine = tmp;\n    }\n    if (l === r) return node;\n\n    if (leftBetter !== midBetter) {\n      node.left = this._insert(node.left, l, mid, newLine);\n    } else {\n      node.right = this._insert(node.right, mid + 1, r, newLine);\n    }\n    return node;\n  }\n\n  query(x) {\n    return this._query(this.root, this.minX, this.maxX, x);\n  }\n\n  _query(node, l, r, x) {\n    if (!node) return Infinity;\n    let res = node.line.eval(x);\n    if (l === r) return res;\n    const mid = Math.floor((l + r) / 2);\n    if (x <= mid) {\n      return Math.min(res, this._query(node.left, l, mid, x));\n    } else {\n      return Math.min(res, this._query(node.right, mid + 1, r, x));\n    }\n  }\n}\n\nclass MonotonicCHT {\n  constructor() {\n    this._hull = [];\n    this._ptr = 0;\n  }\n\n  static _bad(l1, l2, l3) {\n    // Intersection of (l1, l3) <= Intersection of (l1, l2)\n    // (l3.b - l1.b) / (l1.m - l3.m) <= (l2.b - l1.b) / (l1.m - l2.m)\n    return (l3.b - l1.b) * (l1.m - l2.m) <= (l2.b - l1.b) * (l1.m - l3.m);\n  }\n\n  addLine(m, b) {\n    const nl = new Line(m, b);\n    while (this._hull.length >= 2) {\n      const l1 = this._hull[this._hull.length - 2];\n      const l2 = this._hull[this._hull.length - 1];\n      if (MonotonicCHT._bad(l1, l2, nl)) {\n        this._hull.pop();\n      } else {\n        break;\n      }\n    }\n    this._hull.push(nl);\n    if (this._ptr >= this._hull.length) this._ptr = this._hull.length - 1;\n  }\n\n  queryMonotonic(x) {\n    if (this._hull.length === 0) return Infinity;\n    while (\n      this._ptr + 1 < this._hull.length &&\n      this._hull[this._ptr + 1].eval(x) <= this._hull[this._ptr].eval(x)\n    ) {\n      this._ptr++;\n    }\n    return this._hull[this._ptr].eval(x);\n  }\n}\n\nmodule.exports = { LiChaoTree, MonotonicCHT, Line };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Arbitrary (non-monotonic) slopes & queries on LiChaoTree vs brute-force lower envelope\n  const lct = new LiChaoTree(-5000, 5000);\n  const lines = [\n    [3, 10], [-2, 40], [5, -100], [-7, 250], [0, 15], [1, -30], [-4, -10], [8, 90]\n  ];\n  for (const [m, b] of lines) lct.addLine(m, b);\n\n  for (let x = -1000; x <= 1000; x += 17) {\n    let brute = Infinity;\n    for (const [m, b] of lines) brute = Math.min(brute, m * x + b);\n    assert(lct.query(x) === brute, `LiChaoTree query(${x}) expected ${brute}, got ${lct.query(x)}`);\n  }\n\n  // Solve 1D DP: dp[i] = c + min_{j < i} ((x[i] - x[j])^2 + dp[j])\n  // = (x[i]^2 + c) + min_{j < i} (-2 * x[j] * x[i] + (x[j]^2 + dp[j]))\n  const xs = [0, 2, 5, 9, 12, 18, 25, 31, 40];\n  const C = 20;\n  const n = xs.length;\n  const dpBrute = new Float64Array(n).fill(Infinity);\n  const dpLCT = new Float64Array(n).fill(Infinity);\n  const dpCHT = new Float64Array(n).fill(Infinity);\n\n  dpBrute[0] = dpLCT[0] = dpCHT[0] = 0;\n  const dpTree = new LiChaoTree(0, 100);\n  const cht = new MonotonicCHT();\n  dpTree.addLine(-2 * xs[0], xs[0] * xs[0] + dpLCT[0]);\n  cht.addLine(-2 * xs[0], xs[0] * xs[0] + dpCHT[0]);\n\n  for (let i = 1; i < n; i++) {\n    for (let j = 0; j < i; j++) {\n      dpBrute[i] = Math.min(dpBrute[i], (xs[i] - xs[j]) ** 2 + C + dpBrute[j]);\n    }\n    dpLCT[i] = xs[i] * xs[i] + C + dpTree.query(xs[i]);\n    dpCHT[i] = xs[i] * xs[i] + C + cht.queryMonotonic(xs[i]);\n\n    dpTree.addLine(-2 * xs[i], xs[i] * xs[i] + dpLCT[i]);\n    cht.addLine(-2 * xs[i], xs[i] * xs[i] + dpCHT[i]);\n\n    assert(dpLCT[i] === dpBrute[i], `LiChao DP at i=${i}`);\n    assert(dpCHT[i] === dpBrute[i], `Monotonic CHT DP at i=${i}`);\n  }\n\n  return { passed: 4, total: 4 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\n// Execute self-test suite when evaluated directly\nrunTests();\n",
