    "code": "'use strict';\n/**\n * ============================================================================\n * Multi-Dimensional k-d Tree with Branch-and-Bound k-NN & Range Search (build-kd-tree-nearest-neighbor)\n * ============================================================================\n * Category: Computational Geometry & Spatial Indexing\n * Difficulty: Advanced (~45 min)\n * Primary Curriculum Unit: build-kd-tree-nearest-neighbor\n * Related Units: spatial-indexing-kd-quad-rtrees, branch-and-bound-admissible-bounds, quickselect-bfprt-median, binary-d-ary-heaps, augmented-trees-order-intervals\n *\n * Summary:\n *   A balanced multi-dimensional k-d Tree supporting orthogonal bounding-box range queries and branch-and-bound 1-NN / k-NN search with hypersphere-hyperplane pruning telemetry.\n *\n * Key Engineering Highlights:\n *   1. Alternating-axis median partitioning building a balanced k-d tree\n *   2. Branch-and-Bound Nearest Neighbor pruning the far half-space when axisDist^2 >= bestDist^2\n *   3. Bounded Max-Heap k-Nearest Neighbors (k-NN) and orthogonal hyper-rectangle range queries\n *\n * Progressive Implementation Roadmap:\n *   - Step 1: Alternating-Axis Median Partitioning: At depth $d$, select splitting axis $\\text{axis} = d \\bmod k$, sort points along that coordinate, pick the median as the splitting hyperplane, and recursively build left and right subtrees.\n *   - Step 2: Orthogonal Bounding-Box Range Search: Implement `rangeSearch(minBounds, maxBounds)` by pruning the left half-space when `minBounds[axis] > node.point[axis]` and pruning the right half-space when `maxBounds[axis] < node.point[axis]`.\n *   - Step 3: Branch-and-Bound Nearest Neighbor Pruning: Always recurse into the `near` child containing `target` first to shrink `bestSq` quickly. Only recurse into the `far` child if the perpendicular distance to the splitting hyperplane satisfies $(target[axis] - node.point[axis])^2 < bestSq$.\n *   - Step 4: Bounded k-Nearest Neighbors (k-NN): Generalize pruning to $k$ nearest neighbors by comparing the hyperplane distance against the $k$-th best squared distance collected so far.\n * ============================================================================\n */\n\nclass KDNode {\n  constructor(point, payload, axis, left = null, right = null) {\n    this.point = point;\n    this.payload = payload;\n    this.axis = axis;\n    this.left = left;\n    this.right = right;\n  }\n}\n\nclass KDTree {\n  constructor(points = [], dimensions = 2) {\n    this.k = dimensions;\n    this.size = points.length;\n    const normalized = points.map((p, idx) => (p && p.point ? p : { point: p, payload: idx }));\n    this.root = this._build(normalized, 0);\n  }\n\n  static sqDist(a, b) {\n    let s = 0;\n    for (let i = 0; i < a.length; i++) {\n      const d = a[i] - b[i];\n      s += d * d;\n    }\n    return s;\n  }\n\n  _build(items, depth) {\n    if (!items || items.length === 0) return null;\n    const axis = depth % this.k;\n    items.sort((a, b) => a.point[axis] - b.point[axis]);\n    const mid = items.length >> 1;\n    return new KDNode(\n      items[mid].point,\n      items[mid].payload,\n      axis,\n      this._build(items.slice(0, mid), depth + 1),\n      this._build(items.slice(mid + 1), depth + 1)\n    );\n  }\n\n  rangeSearch(minBounds, maxBounds) {\n    const results = [];\n    const dfs = (node) => {\n      if (!node) return;\n      let inside = true;\n      for (let d = 0; d < this.k; d++) {\n        if (node.point[d] < minBounds[d] || node.point[d] > maxBounds[d]) {\n          inside = false;\n          break;\n        }\n      }\n      if (inside) results.push({ point: node.point, payload: node.payload });\n\n      const axis = node.axis;\n      if (minBounds[axis] <= node.point[axis]) dfs(node.left);\n      if (maxBounds[axis] >= node.point[axis]) dfs(node.right);\n    };\n    dfs(this.root);\n    return results;\n  }\n\n  nearestNeighbor(target) {\n    let bestNode = null;\n    let bestSq = Infinity;\n    let visitedNodes = 0;\n\n    const search = (node) => {\n      if (!node) return;\n      visitedNodes++;\n      const dSq = KDTree.sqDist(node.point, target);\n      if (dSq < bestSq) {\n        bestSq = dSq;\n        bestNode = node;\n      }\n      const axis = node.axis;\n      const diff = target[axis] - node.point[axis];\n      const near = diff <= 0 ? node.left : node.right;\n      const far = diff <= 0 ? node.right : node.left;\n\n      search(near);\n      if (diff * diff < bestSq) {\n        search(far);\n      }\n    };\n\n    search(this.root);\n    return {\n      point: bestNode ? bestNode.point : null,\n      payload: bestNode ? bestNode.payload : null,\n      distance: Math.sqrt(bestSq),\n      visitedNodes\n    };\n  }\n\n  kNearestNeighbors(target, kCount = 1) {\n    const pool = []; // kept sorted ascending by sqDist, max length kCount\n\n    const search = (node) => {\n      if (!node) return;\n      const dSq = KDTree.sqDist(node.point, target);\n      if (pool.length < kCount || dSq < pool[pool.length - 1].sqDist) {\n        pool.push({ point: node.point, payload: node.payload, sqDist: dSq, distance: Math.sqrt(dSq) });\n        pool.sort((a, b) => a.sqDist - b.sqDist);\n        if (pool.length > kCount) pool.pop();\n      }\n      const axis = node.axis;\n      const diff = target[axis] - node.point[axis];\n      const near = diff <= 0 ? node.left : node.right;\n      const far = diff <= 0 ? node.right : node.left;\n\n      search(near);\n      const worstSq = pool.length < kCount ? Infinity : pool[pool.length - 1].sqDist;\n      if (diff * diff < worstSq) {\n        search(far);\n      }\n    };\n\n    search(this.root);\n    return pool;\n  }\n}\n\nmodule.exports = { KDTree };\n\n// ============================================================================\n// Deterministic Verification & Self-Test Harness\n// ============================================================================\nfunction runTests() {\n  const assert = (cond, msg) => { if (!cond) throw new Error('Assertion failed: ' + msg); };\n\n  // Deterministic pseudo-random 2D point cloud of 250 points\n  let seed = 42;\n  const rand = () => {\n    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;\n    return (seed & 0xffff) / 65536 * 1000;\n  };\n  const pts = Array.from({ length: 250 }, (_, i) => ({ point: [rand(), rand()], payload: i }));\n  const tree = new KDTree(pts, 2);\n\n  // Verify 20 random queries against brute force for 1-NN and 5-NN\n  for (let q = 0; q < 20; q++) {\n    const target = [rand(), rand()];\n    const sortedBrute = pts\n      .map(p => ({ ...p, sqDist: KDTree.sqDist(p.point, target) }))\n      .sort((a, b) => a.sqDist - b.sqDist);\n\n    const nn = tree.nearestNeighbor(target);\n    assert(Math.abs(nn.distance - Math.sqrt(sortedBrute[0].sqDist)) < 1e-9, '1-NN exact match');\n    assert(nn.visitedNodes < pts.length, 'Branch-and-bound prunes search space');\n\n    const knn = tree.kNearestNeighbors(target, 5);\n    assert(knn.length === 5, '5-NN returns 5 points');\n    for (let i = 0; i < 5; i++) {\n      assert(Math.abs(knn[i].sqDist - sortedBrute[i].sqDist) < 1e-7, `5-NN rank ${i} distance match`);\n    }\n  }\n\n  // Orthogonal bounding box range query verification\n  const minB = [200, 300], maxB = [650, 750];\n  const found = tree.rangeSearch(minB, maxB).map(r => r.payload).sort((a, b) => a - b);\n  const expected = pts\n    .filter(p => p.point[0] >= 200 && p.point[0] <= 650 && p.point[1] >= 300 && p.point[1] <= 750)\n    .map(p => p.payload)\n    .sort((a, b) => a - b);\n  assert(JSON.stringify(found) === JSON.stringify(expected), 'Orthogonal rangeSearch exact match');\n\n  return { passed: 4, total: 4 };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports.runTests = runTests;\n}\n\n// Execute self-test suite when evaluated directly\nrunTests();\n",
